#include <CurrencyAwardsSql.hpp>
#include <StoragePersistenceSql.hpp>
#include <item/NativeMoneyWire.hpp>
#include <item/TokenRedemption.hpp>
#include <item/TypedGround.hpp>
void NativeMoneyCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==2 && catalog->CurrencyKey(CurrencyTokenMode::GroundGold) && catalog->CurrencyKey(CurrencyTokenMode::DynamicGold),"both original native money definitions present");
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned money SQL connects");
 const auto query=[&](const std::string& text){std::unique_ptr<SQLMsg> result(sql.DirectQuery(text.c_str()));Check(result && !result->uiSQLErrno,"owned money fixture SQL succeeds");};
 auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-native-money-worker").has_value(),"actual native money worker starts");
 constexpr std::uint64_t amount=7000000001ULL,cap=999000000000ULL;const ItemOwner owner{ItemOwnerKind::Character,23001},account{ItemOwnerKind::Account,71},wrongAccount{ItemOwnerKind::Account,72};
 const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,1000}};
 Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"native money character provisioned");
 Check(persistence::EnsureRuntimeStorageOwner(sql,*catalog,account).has_value() && persistence::EnsureRuntimeStorageOwner(sql,*catalog,wrongAccount).has_value(),"native account bank owners provisioned");
 auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();auto bank=persistence::LoadCurrentItemOwner(sql,*catalog,account).value();unsigned serial=0,packets=0;bool replay=false;
 const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0x56,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
 const auto wait=[&](const auto& done){for(unsigned n=0;!done() && n<1000;++n){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(done(),"native money worker completion returned");};
 const auto apply=[&](const ItemCommit& commit,bool expect=true){
  std::vector<runtime::OwnerRead> reads;for(const auto& f:commit.owners)reads.push_back({f.owner,f.sessionGeneration});std::optional<runtime::MultiCommitOutcome> result;
  Check(runtime::RequestCommitMany(reads,commit,[&](auto out){result=std::move(out);}),"native money commit queued");wait([&](){return result.has_value();});Check(result->write.has_value()==expect,"native money SQL write agrees with expected outcome");replay=result->write && result->write->replay;
  for(auto& loaded:result->states)if(loaded){if(loaded->fence.owner==owner)state=std::move(*loaded);else if(loaded->fence.owner==account)bank=std::move(*loaded);}
 };
 const auto deliver=[&](ItemOwner target,std::string login){std::optional<std::expected<unsigned,ItemPersistenceError>> result;Check(store.Submit([&result,target,login](CAsyncSQL& db,const ItemCatalog& c){auto delivered=persistence::DeliverCurrencyAwards(db,c,target,login);return [&result,delivered](){result=delivered;};}),"real authenticated award delivery queued on store thread");wait([&](){return result.has_value();});return *result;};
 query("INSERT INTO player.item_currency_award(login,amount,reason_kind) VALUES('moneytest',7000000001,1),('moneytest',2,2),('moneytest',3,3),('moneytest',4,4)");
 Check(!deliver(wrongAccount,"moneytest"),"wrong account cannot claim another login's pending payout");
 Check(persistence::LoadCurrentItemOwner(sql,*catalog,wrongAccount)->items.empty(),"refused award does not create an orphan pouch");
 const auto issued=deliver(account," MONEYTEST ");Check(issued && *issued==4,"all four actual guild refund and settlement reasons deliver exact native bank pouches");
 bank=persistence::LoadCurrentItemOwner(sql,*catalog,account).value();Check(bank.items.size()==4 && state.items.empty(),"payouts arrive in account safebox without changing the character bag");
 const auto again=deliver(account,"moneytest");Check(again && *again==0,"bank reopening cannot deliver claimed payouts again");
 const auto pouch=*std::ranges::find_if(bank.items,[](const auto& i){return i.currencyAmount==amount;});Check(pouch.owner==account && pouch.placement->kind==ItemStorageKind::Safebox,"real 64-bit pouch persisted in correct native storage");
 const auto file=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream out(path+"."+phase+"."+kind+".hex");for(auto b:bytes){auto x=static_cast<unsigned char>(b);out<<"0123456789abcdef"[x>>4]<<"0123456789abcdef"[x&15];}out<<'\n';Check(out.good(),"actual money frame exported");};
 const auto output=[&](const std::string& phase){file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());std::ofstream facts(path+"."+phase+".json");facts<<"{\"source\":"<<pouch.id.Value()<<",\"amount\":"<<amount<<",\"balance\":"<<state.wallets[0].balance<<",\"count\":"<<state.items.size()<<"}\n";++packets;};
 StorageActor actor{23001,71,0,{100,0,0},true,true};StorageSnapshot snapshot;snapshot.actor=actor;snapshot.route=StorageRoute::Bank;snapshot.owner=account;snapshot.items=bank.items;snapshot.canWithdraw=true;for(const auto& l:bank.storages)if(l.storage.kind==ItemStorageKind::Safebox)snapshot.layouts.push_back(l);
 file("bank_received","storage",EncodeStorageSnapshot(*catalog,snapshot).value());output("bank_received");
 auto all=bank.items;all.insert(all.end(),state.items.begin(),state.items.end());auto storage=bank.storages;storage.insert(storage.end(),state.storages.begin(),state.storages.end());const std::array fences{state.fence,bank.fence};
 const auto take=MakeStorageCommit(*catalog,op(),fences,storage,all,state.wallets,actor,{StorageRoute::Bank,StorageCommand::Withdraw,pouch.id.Value()});Check(take.has_value(),"actual bank withdrawal plans native ownership transfer");apply(take->commit);Check(state.items.size()==1 && state.items[0].currencyAmount==amount && bank.items.size()==3,"withdrawal preserves exact payout amount and identity");output("withdrawn");
 const TokenRedemptionActor tokenActor{100,0,0,false};const auto redeem=MakeTokenRedemptionCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,pouch.id,1,cap,tokenActor);Check(redeem && redeem->quote.credit==amount,"actual original payout prepares exact redemption");
 file("token_ready","token",EncodeTokenRedemption(*catalog,5600,&state.items[0],state.fence.revision,TokenRedemptionStatus::Ready,redeem->quote).value());output("token_ready");apply(redeem->commit);Check(state.items.empty() && state.wallets[0].balance==amount+1000,"SQL atomically redeems the 64-bit payout");output("redeemed");apply(redeem->commit);Check(replay && state.wallets[0].balance==amount+1000,"actual receipt replay cannot duplicate money");output("redeem_replayed");
 const auto saved=state;auto session=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,session).value();Check(state.items==saved.items && state.wallets==saved.wallets,"actual relog retains authoritative wallet balance");output("relogged");
 const auto run=store.GroundRun().value();const auto now=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());
 CurrencyDropIntent intent{op(),run.core,run.run,owner.id,amount,now,now+300000,now,1,100,200,0,true};const auto drop=MakeCurrencyDropCommit(*catalog,intent.operation,state.fence,state.wallets[0],intent);Check(drop.has_value(),"actual 64-bit wallet drop plans durable publication intent");
 file("drop_ready","money",EncodeNativeMoney({NativeMoneyStatus::Ready,5601,amount,state.wallets[0].balance,state.fence.revision,cap}).value());output("drop_ready");apply(*drop);Check(state.wallets[0].balance==1000,"drop debit is authoritative SQL wallet balance");file("dropped","money",EncodeNativeMoney({NativeMoneyStatus::Applied,5601,amount,state.wallets[0].balance,state.fence.revision,cap}).value());
 file("dropped","ground",EncodeTypedGround({5602,100,200,0,*catalog->CurrencyKey(CurrencyTokenMode::GroundGold),0,1,"currency.ground_gold",amount}).value());output("dropped");
 apply(*drop);Check(replay && state.wallets[0].balance==1000,"drop replay cannot debit or create intent twice");output("drop_replayed");
 auto pickup=MakeGroundCurrencyCredit(*catalog,op(),state.fence,state.wallets[0],*catalog->CurrencyKey(CurrencyTokenMode::GroundGold),amount,cap).value();intent.create=false;intent.nowAtMs=now+1;pickup.currencyDrop=intent;Check(ValidateItemCommit(*catalog,pickup).has_value(),"exact original drop claim and credit validate together");apply(pickup);Check(state.wallets[0].balance==amount+1000,"actual pickup claims durable row and credits the whole Yang amount");output("picked");apply(pickup);Check(replay && state.wallets[0].balance==amount+1000,"pickup receipt replay cannot credit twice");output("pickup_replayed");
 auto second=MakeGroundCurrencyCredit(*catalog,op(),state.fence,state.wallets[0],*catalog->CurrencyKey(CurrencyTokenMode::GroundGold),amount,cap).value();second.currencyDrop=intent;apply(second,false);Check(state.wallets[0].balance==amount+1000,"another operation cannot claim an already picked drop");output("duplicate_denied");
 auto expired=intent;expired.nowAtMs=expired.expiresAtMs;second.currencyDrop=expired;Check(!ValidateItemCommit(*catalog,second),"expired original drop is refused before SQL");
 auto capped=state.wallets[0];capped.balance=cap-amount+1;Check(!MakeGroundCurrencyCredit(*catalog,op(),state.fence,capped,*catalog->CurrencyKey(CurrencyTokenMode::GroundGold),amount,cap),"wallet cap refuses the entire ground credit without claiming it");output("cap_denied");
 const ItemOwner lateOwner{ItemOwnerKind::Character,23002};const std::array lateLayouts{ItemStorageLayout{{lateOwner,ItemStorageKind::Inventory,1},5,9,1}};const std::array lateWallets{ItemWallet{lateOwner,WalletCurrency::Gold,1,1000}};
 Check(persistence::ProvisionOwner(sql,*catalog,lateOwner,lateLayouts,lateWallets).has_value(),"delayed-pickup owner provisioned");auto late=persistence::LoadCurrentItemOwner(sql,*catalog,lateOwner).value();
 CurrencyDropIntent oldIntent{op(),run.core,run.run,lateOwner.id,500,now-600000,now-300000,now-600000,1,100,200,0,true};const auto oldDrop=MakeCurrencyDropCommit(*catalog,oldIntent.operation,late.fence,late.wallets[0],oldIntent).value();apply(oldDrop);late=persistence::LoadCurrentItemOwner(sql,*catalog,lateOwner).value();
 auto delayed=MakeGroundCurrencyCredit(*catalog,op(),late.fence,late.wallets[0],*catalog->CurrencyKey(CurrencyTokenMode::GroundGold),500,cap).value();oldIntent.create=false;++oldIntent.nowAtMs;delayed.currencyDrop=oldIntent;
 Check(ValidateItemCommit(*catalog,delayed).has_value(),"pickup was admissible at its original captured request time");apply(delayed,false);Check(persistence::LoadCurrentItemOwner(sql,*catalog,lateOwner)->wallets[0].balance==500,"actual SQL transaction time refuses expired queued pickup without credit");
 store.Stop();std::cout<<"SOURCE_NATIVE_MONEY_WORKER=SUCCESS sources=2 packets="<<packets<<" checks="<<checks<<std::endl;
}
